Input: {"question": "What political party was Governor Olson a member of?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 0, "end": 8, "text": "Allen I."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 9, "end": 174, "text": "Olson Allen Ingvar Olson (born November 5, 1938) is an American Republican politician and attorney who served as the 28th Governor of North Dakota from 1981 to 1985."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 175, "end": 206, "text": "He defeated incumbent Arthur A."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 207, "end": 262, "text": "Link in the 1980 race for governor and served one term."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 263, "end": 340, "text": "Olson was born on November 5, 1938, in the small town of Rolla, North Dakota."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 341, "end": 526, "text": "He received a law degree from the University of North Dakota where he joined Lambda Chi Alpha Fraternity and served in the United States Army as a judge advocate general's corps lawyer."}, "D1S7": {"document_number": 1, "doc_id": "ramdocs-0373-d6b270ce4070:d00", "start": 527, "end": 556, "text": "In 1967 he served as Chief of"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 0, "end": 8, "text": "Floyd B."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 9, "end": 116, "text": "Olson Floyd Bjørnstjerne Olson (November 13, 1891 – August 22, 1936) was an American politician and lawyer."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 117, "end": 237, "text": "He served as the 22nd Governor of Minnesota from January 6, 1931, to August 22, 1936, dying in office of stomach cancer."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 238, "end": 359, "text": "Olson was a member of the Minnesota Farmer-Labor Party, and the first member of that party to win the office of governor."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 360, "end": 505, "text": "He is consistently considered one of the greatest governors in Minnesota history and one of the most influential American politicians of his era."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 506, "end": 514, "text": "Floyd B."}, "D2S7": {"document_number": 2, "doc_id": "ramdocs-0373-d6b270ce4070:d01", "start": 515, "end": 583, "text": "Olson was born on the north side of Minneapolis, Minnesota, the only"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 0, "end": 107, "text": "Culbert Olson Culbert Levy Olson (November 7, 1876 – April 13, 1962) was an American lawyer and politician."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 108, "end": 255, "text": "A Democratic Party member, Olson was involved in Utah and California politics and was elected as the 29th governor of California from 1939 to 1943."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 256, "end": 374, "text": "Olson was born in Fillmore, Utah, the son of Delilah Cornelia (née King) and George Daniel Olson, on November 7, 1876."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 375, "end": 461, "text": "Olson's mother was a suffragette and became the first female elected official in Utah."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 462, "end": 549, "text": "Both his mother and father belonged to The Church of Jesus Christ of Latter-day Saints."}, "D3S6": {"document_number": 3, "doc_id": "ramdocs-0373-d6b270ce4070:d02", "start": 550, "end": 599, "text": "However, Culbert was unconvinced of the existence"}}, "original_cards": [{"doc_id": "ramdocs-0373-d6b270ce4070:d00", "card_id": "ramdocs-0373-d6b270ce4070:d00:c0", "entity": "Olson", "scope": "Governor of North Dakota", "claim": "Olson Allen Ingvar Olson is an American Republican politician who served as the 28th Governor of North Dakota.", "answer": "Republican", "quote": "Olson Allen Ingvar Olson (born November 5, 1938) is an American Republican politician and attorney who served as the 28th Governor of North Dakota from 1981 to 1985.", "original_document_number": 1}, {"doc_id": "ramdocs-0373-d6b270ce4070:d01", "card_id": "ramdocs-0373-d6b270ce4070:d01:c0", "entity": "Governor Olson", "scope": "Political party membership", "claim": "Olson was a member of the Minnesota Farmer-Labor Party.", "answer": "Minnesota Farmer-Labor Party", "quote": "Olson was a member of the Minnesota Farmer-Labor Party, and the first member of that party to win the office of governor.", "original_document_number": 2}, {"doc_id": "ramdocs-0373-d6b270ce4070:d02", "card_id": "ramdocs-0373-d6b270ce4070:d02:c0", "entity": "Culbert Olson", "scope": "Governor of California", "claim": "Culbert Olson was a member of the Democratic Party.", "answer": "Democratic Party", "quote": "A Democratic Party member, Olson was involved in Utah and California politics and was elected as the 29th governor of California from 1939 to 1943.", "original_document_number": 3}], "current_answers": ["Republican", "Minnesota Farmer-Labor Party", "Democratic Party"], "candidate_answers": [{"candidate_id": "R0", "answer": "Republican", "origin": "initial"}, {"candidate_id": "R1", "answer": "Minnesota Farmer-Labor Party", "origin": "initial"}, {"candidate_id": "R2", "answer": "Democratic Party", "origin": "initial"}], "requested_slot_hint": "political_party"}

